import Card from "./Card";
import React,{useState} from "react";
function Cards({ courses,category }) {
    const [likedCourses,setLikedCourses]=useState([]);
  const getCourses = () => {
    if(category==="All")
    {
        if (!courses || Object.keys(courses).length === 0) return []; // Ensure courses is valid

        let allCourses = [];
        Object.values(courses).forEach((courseCategory) => {
          if (Array.isArray(courseCategory)) {
            allCourses.push(...courseCategory);
          }
        });
        return allCourses;
    }
    else{
        //main sirf specific category ka arrya pass krunga
        return courses[category] || [];
    }
   
  };

  return (
    <div className="flex flex-wrap justify-center gap-4 mb-4">
      {!courses ? (
        <div>Loading...</div> // Show a loading message when courses are undefined
      ) : (
        getCourses().map((course, index) => <Card key={index} course={course}
        likedCourses={likedCourses}
        setLikedCourses={setLikedCourses} />)
      )}
    </div>
  );
}

export default Cards;
