import { FcLike,FcLikePlaceholder } from "react-icons/fc";
import Cards from "./Cards";
import React from "react"; 
import { toast } from 'react-toastify';

 function Card({course,likedCourses = [],setLikedCourses}){
    function clickHandler(){
        //logic
      if(likedCourses.includes(course.id)){
        //pehle se liked hau pada tha
        setLikedCourses((prev)=>prev.filter((cid)=>(cid!==course.id)));
        toast.warning("Like Removed");
      }
      else{
        //pehle se like nhi hai
        //insert kran hai yee course liked courses me
        if(likedCourses.length===0)
        {
            setLikedCourses([course.id]);
        }
        else{
             //non-empty pehle se
             setLikedCourses((prev)=>[...prev,course.id]);
             toast.success("Liked!");
        }
      }
    }
   return(
    <div className="bg-[#001933] bg-opacity-70 w-[300px] rounded-md overflow-hidden">
  <div className="relative">
    <img src={course.image.url} alt={course.title} className="w-full h-auto" />
    <div className="w-[40px] h-[40px] bg-white rounded-full absolute right-2 bottom-[-12px] grid place-items-center">
      <button onClick={clickHandler}>
        {likedCourses.includes(course.id) ?  (<FcLike fontSize="1.75rem"/>) : (<FcLikePlaceholder fontSize="1.75rem"/>) }
      </button>
    </div>
  </div>
  <div className="p-4">
    <p className="text-white font-semibold text-lg leading-6">{course.title}</p>
    <p className="text-white mt-[2px]">
        {
            course.description.length>100 ? (course.description.substr(0,100)) + "...": (course.description)
        }

    </p>
  </div>
</div>

   )
 }
 export default Card;